#!/usr/bin/env python3
"""ANUGA rain-on-grid run, generated by DamIT PMP (damit_pmp:anugarain). Run it in the ANUGA Python.

    python run_anuga_rain.py                 # default: --dry (build everything, evolve nothing)
    python run_anuga_rain.py --dry           # mesh (if missing), domain, rate operator, mass check; no evolve
    python run_anuga_rain.py --steps 2       # the same, then evolve this many yield steps (after t = 0) and stop
    python run_anuga_rain.py --run           # the full simulation (long on a fine mesh)
    python run_anuga_rain.py --mesh          # (re)build the gmsh mesh first with the runner's mesher

The folder is self-contained: gmsh_mesher.py, anuga_worker.py, omp_probe.py and anuga_dtdiag.py are
byte copies of damit_runner/core (see run_manifest.json for their sha256), anuga_rain_job.npz holds the
DEM, the rain series (m/s) and the settings, gmsh_mesh_in.json the mesher input. The domain is built the way
the runner's anuga_worker.build_domain does it for a gmsh mesh: local coordinates (the DEM's lower left is
0, 0), a zero Geo_reference, every outer edge tagged "outflow", the runner's flow algorithm / minimum storable
height / Manning n / dry start, the ground height from the model DEM (bilinear at the centroids) or, when the
job has a finer DEM, at the vertices (the worker's sample_fine), and make_outer_boundary for edge_bc. The
runner's worker only has a breach inlet; the rain is an anuga.Rate_operator on the whole mesh whose rate (m/s)
is the series in the job times the optional per-triangle factor.

--steps and --run also report the water balance (--steps: anuga_rain_steps.json and anuga_rain_steps_timeseries.csv,
--run: anuga_rain_run.json and anuga_rain_timeseries.csv; --dry: anuga_rain_dry_check.json; no mode overwrites another): the
exact rain volume put on the mesh, the water stored, the outflow through the outer boundary (ANUGA's boundary
flux integral), the residual, the maximum depth and the wet area (depth over 5 cm / 30 cm at any time).
"""
import hashlib
import json
import os
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import numpy as np  # noqa: E402


class RainRate:
    """Rate (m/s) of the Rate_operator as f(x, y, t): the series at time t times the factor of each
    triangle (given once, in triangle order; the operator calls with the centroid coordinates)."""

    def __init__(self, t, r, factor_per_triangle=None):
        self.t = np.asarray(t, float)
        self.r = np.asarray(r, float)
        self.f = None if factor_per_triangle is None else np.asarray(factor_per_triangle, float)

    def series(self, t_now):
        return float(np.interp(t_now, self.t, self.r, left=0.0, right=0.0))

    def __call__(self, x, y, t):
        s = self.series(t)
        if self.f is None:
            return s + 0.0 * np.asarray(x, float)
        return s * self.f


def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for blk in iter(lambda: fh.read(1 << 20), b""):
            h.update(blk)
    return h.hexdigest()


def build_mesh(mesh_path):
    """The runner's stand-alone mesher, in this process (gmsh_mesher.main = its command line)."""
    import gmsh_mesher
    rc = gmsh_mesher.main(["gmsh_mesher.py", os.path.join(HERE, "gmsh_mesh_in.json"), mesh_path])
    if rc != 0:
        raise SystemExit("the gmsh mesh failed (see MESHERROR above)")


def build_domain(anuga, W, job, mesh):
    """The runner's gmsh-mesh domain (anuga_worker.build_domain), dry start, no breach inlet."""
    s = lambda k: float(job[k])
    dem = W.fill_nan(job["dem"].astype(float))
    dx = s("dem_dx")
    x_ref, y_ref = s("dem_x0"), s("dem_y0") - dem.shape[0] * dx
    lx0, ly0 = 0.0, dem.shape[0] * dx

    def to_local(p):
        p = np.asarray(p, dtype=float).reshape(-1, 2)
        return np.column_stack([p[:, 0] - x_ref, p[:, 1] - y_ref])

    georef = anuga.Geo_reference(xllcorner=0.0, yllcorner=0.0)
    pts = to_local(mesh["mesh_points"])
    tris = np.asarray(mesh["mesh_triangles"], dtype=int)
    bnd = {(int(t), int(e)): "outflow" for t, e in np.asarray(mesh["mesh_boundary"], int)}
    domain = anuga.Domain(pts.tolist(), tris.tolist(), bnd, geo_reference=georef)
    domain.set_name("anuga_rain")
    domain.set_store(False)
    try:
        domain.set_flow_algorithm(str(job["algorithm"]))
    except Exception:
        domain.set_flow_algorithm("DE0")
    domain.set_minimum_storable_height(0.001)
    elev = {"mode": "model_grid", "cell_m": dx}
    if "elev_fine_file" in job:
        farr = np.load(os.path.join(HERE, str(job["elev_fine_file"])), mmap_mode="r")
        fx0, fy0, fdx = s("elev_fine_x0"), s("elev_fine_y0"), s("elev_fine_dx")
        count = {"vertices": 0, "fallback": 0}

        def elevation(x, y):
            x = np.asarray(x, float)
            y = np.asarray(y, float)
            v = W.sample_fine(farr, fx0, fy0, fdx, x.ravel() + x_ref, y.ravel() + y_ref)
            bad = ~np.isfinite(v)
            if bad.any():
                v[bad] = W.bilinear(dem, lx0, ly0, dx, x.ravel()[bad], y.ravel()[bad])
            count["vertices"] += int(v.size)
            count["fallback"] += int(bad.sum())
            return v.reshape(x.shape)
        domain.set_quantity("elevation", elevation, location="vertices")
        elev = {"mode": "fine", "cell_m": fdx, "sampled_at": "vertices", "vertex_samples": count["vertices"],
                "model_grid_fallback_samples": count["fallback"]}
    else:
        domain.set_quantity("elevation", lambda x, y: W.bilinear(dem, lx0, ly0, dx, x, y), location="centroids")
    domain.set_quantity("friction", s("manning_n"))
    domain.set_quantity("stage", expression="elevation", location="centroids")     # dry start
    Bo, bkind = W.make_outer_boundary(anuga, domain, str(job["edge_bc"]), np.nanmin(dem))
    domain.set_boundary({"outflow": Bo})
    info = {"elevation": elev, "boundary": bkind, "dem_min_m": float(np.nanmin(dem)),
            "dem_max_m": float(np.nanmax(dem))}
    return domain, info, (x_ref, y_ref, lx0, ly0, dx)


def main(argv):
    mode_run = "--run" in argv
    steps = int(argv[argv.index("--steps") + 1]) if "--steps" in argv else 0
    t_wall = time.time()
    job = dict(np.load(os.path.join(HERE, "anuga_rain_job.npz"), allow_pickle=False))
    mesh_path = os.path.join(HERE, "gmsh_mesh.npz")
    if "--mesh" in argv or not os.path.exists(mesh_path):
        build_mesh(mesh_path)
    mesh = dict(np.load(mesh_path, allow_pickle=False))
    stats = json.loads(str(mesh["mesh_stats"]))

    import anuga
    import anuga_worker as W
    omp, note = W.apply_threads(anuga, int(job["threads"]))
    domain, info, (x_ref, y_ref, lx0, ly0, dx) = build_domain(anuga, W, job, mesh)
    n = len(domain)
    areas = np.asarray(domain.areas, float)
    fac = None
    fstats = None
    if "factor" in job:
        c = domain.centroid_coordinates
        fac = W.bilinear(W.fill_nan(job["factor"].astype(float)), lx0, ly0, dx, c[:, 0], c[:, 1])
        fstats = {"min": float(fac.min()), "max": float(fac.max()),
                  "area_weighted_mean": float((fac * areas).sum() / areas.sum())}
    rate = RainRate(job["rain_t"], job["rain_rate"], fac)
    rain_op = anuga.Rate_operator(domain, rate=rate)
    xsec = None
    if "gauge" in job:                    # optional discharge section (two points, DEM CRS): flow through it every yield step
        from anuga.shallow_water.shallow_water_domain import Cross_section
        gl = np.asarray(job["gauge"], float).reshape(2, 2)
        xsec = Cross_section(domain, [[gl[0, 0] - x_ref, gl[0, 1] - y_ref], [gl[1, 0] - x_ref, gl[1, 1] - y_ref]])
    # mass check for the wiring: the storm volume the operator will add (m3), without evolving
    depth_m = float(np.trapz(job["rain_rate"], job["rain_t"])) if hasattr(np, "trapz") \
        else float(np.trapezoid(job["rain_rate"], job["rain_t"]))
    per_tri = depth_m * (fac if fac is not None else 1.0)
    volume_m3 = float((per_tri * areas).sum())
    rec = {
        "script": os.path.basename(__file__), "triangles": n, "area_km2": float(areas.sum() / 1e6),
        "mesh_sha256": sha256(mesh_path), "mesh_stats": stats, "anuga_version": getattr(anuga, "__version__", "?"),
        "omp_threads": omp, "omp_note": note, "rate_operator_rate_type": getattr(rain_op, "rate_type", None),
        "storm_depth_mm": depth_m * 1000.0, "storm_volume_m3": volume_m3,
        "storm_volume_check_mm_over_area": volume_m3 / float(areas.sum()) * 1000.0,
        "factor": fstats, "sim_time_s": float(job["sim_time"]), "yieldstep_s": float(job["yieldstep"]),
        "peak_rate_mm_hr": float(np.max(job["rain_rate"]) * 3.6e6), "evolved_steps": 0,
    }
    rec.update(info)
    if mode_run or steps > 0:
        ystep = float(job["yieldstep"])
        final = float(job["sim_time"]) if mode_run else ystep * steps
        total_area_f = float((fac * areas).sum()) if fac is not None else float(areas.sum())
        rt, rr = np.asarray(job["rain_t"], float), np.asarray(job["rain_rate"], float)

        def rain_in_m3(t_now):
            """Exact volume (m3) the rain series has put on the mesh by t_now (piecewise-linear rate)."""
            tt = np.clip(t_now, rt[0], rt[-1])
            k = int(np.searchsorted(rt, tt, side="right")) - 1
            k = min(max(k, 0), len(rt) - 2)
            full = np.trapz(rr[:k + 1], rt[:k + 1]) if hasattr(np, "trapz") else np.trapezoid(rr[:k + 1], rt[:k + 1])
            r_tt = float(np.interp(tt, rt, rr))
            return (float(full) + 0.5 * (rr[k] + r_tt) * (tt - rt[k])) * total_area_f
        hmax = np.zeros(n)
        series = []
        k = 0
        for t in domain.evolve(yieldstep=ystep, finaltime=final):
            k += 1
            d = domain.quantities["stage"].centroid_values - domain.quantities["elevation"].centroid_values
            hmax = np.maximum(hmax, d)
            vol = float((d * areas).sum())
            rain = rain_in_m3(t)
            try:
                bflux = float(domain.get_boundary_flux_integral())
            except Exception:                    # noqa: BLE001 - not DE flow, or the setter differs
                bflux = float("nan")
            try:
                frac = float(domain.get_fractional_step_volume_integral())
            except Exception:                    # noqa: BLE001
                frac = float("nan")
            gq = float(xsec.get_flow_through_cross_section()) if xsec is not None else float("nan")
            series.append((float(t), rain, vol, bflux, frac, float(d.max()), float(areas[d > 0.05].sum()), gq))
            print("t = {:.0f} s  max depth {:.4f} m  stored {:.1f} m3  rain in {:.1f} m3".format(
                t, float(d.max()), vol, rain), flush=True)
            if not mode_run and k >= steps + 1:      # the first yield is the initial state (t = 0)
                break
        rec["evolved_steps"] = max(k - 1, 0)
        if series:
            tl = series[-1]
            # balance: rain in = stored + left through the outer boundary. ANUGA's own totals (boundary flux
            # integral, fractional-step volume = what Rate_operator added) are recorded next to the exact rain
            # volume computed here; the outflow is what the boundary flux says, else rain in - stored.
            outflow = -tl[3] if tl[3] == tl[3] else float("nan")
            rec["balance"] = {
                "time_s": tl[0], "rain_in_m3": tl[1], "stored_m3": tl[2], "boundary_flux_integral_m3": tl[3],
                "outflow_m3_from_boundary_flux": outflow, "anuga_rate_operator_volume_m3": tl[4],
                "residual_m3": (tl[1] - tl[2] - outflow) if outflow == outflow else None,
                "residual_percent_of_rain": (100.0 * (tl[1] - tl[2] - outflow) / tl[1])
                if outflow == outflow and tl[1] > 0 else None,
                "outflow_m3_by_difference": tl[1] - tl[2], "max_depth_m": float(hmax.max()),
                "wet_area_km2_depth_over_5cm_at_max": float(areas[hmax > 0.05].sum() / 1e6),
                "wet_area_km2_depth_over_30cm_at_max": float(areas[hmax > 0.30].sum() / 1e6),
                "wet_triangles_over_5cm": int((hmax > 0.05).sum())}
            if xsec is not None:
                ss = np.array(series)
                q = ss[:, 7]
                ia = int(np.argmax(np.abs(q)))
                vol = float(np.trapz(np.abs(q), ss[:, 0])) if hasattr(np, "trapz") else float(np.trapezoid(np.abs(q), ss[:, 0]))
                rec["gauge"] = {"line_xy": gl.tolist(), "segments": len(xsec.segments),
                                "peak_abs_m3_s": float(abs(q[ia])), "t_peak_s": float(ss[ia, 0]),
                                "signed_q_at_peak_m3_s": float(q[ia]), "volume_abs_m3": vol,
                                "note": "flow through the section from the centroid momentum of the cut triangles, sampled "
                                        "once per yield step; the sign is the section's normal direction"}
            np.savetxt(os.path.join(HERE, "anuga_rain_timeseries.csv" if mode_run else "anuga_rain_steps_timeseries.csv"), np.array(series), delimiter=",",
                       header="t_s,rain_in_m3,stored_m3,boundary_flux_integral_m3,rate_operator_m3,max_depth_m,wet_area_m2,gauge_q_m3_s",
                       comments="")
        if mode_run:
            np.savez(os.path.join(HERE, "anuga_rain_result.npz"), hmax_m=hmax,
                     centroids=np.asarray(domain.centroid_coordinates) + np.array([x_ref, y_ref]))
    rec["wall_s"] = round(time.time() - t_wall, 2)
    out = os.path.join(HERE, "anuga_rain_run.json" if mode_run else "anuga_rain_steps.json" if steps > 0
                       else "anuga_rain_dry_check.json")           # each mode has its own file: none overwrites another
    with open(out, "w", encoding="utf-8") as fh:
        json.dump(rec, fh, indent=2, sort_keys=True)
    print("DAMIT_PMP_ANUGA " + ("RUN" if mode_run else "STEPS {}".format(steps) if steps else "DRY")
          + " OK: {} triangles, storm {:.1f} mm, volume {:.0f} m3 -> {}".format(
              n, rec["storm_depth_mm"], volume_m3, os.path.basename(out)), flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
